#include "Engine/Source/Gx/CGxDeviceD3d11/D3d11Water.h"

// MODIFIED: modern water, see D3d11Water.h. The passes' HLSL, apart so Tools/WaterTests can compile it

namespace GxD3d11 {

const char* const s_hlslWaterPasses =
    "// Generated by CGxDeviceD3d11 (D3d11Water.cpp): the ripple height field and its foam, the depth copy.\n"
    "cbuffer GxWaterPass : register(b0) {\n"
    "    int4 wsShift;               // xy the field's shift (texels), z a seed, w the field's size\n"
    "    float4 wsWave;              // x (speed * dt / texel)^2, y damping per step, z raindrop chance, w drop depth\n"
    "    float4 wsImpulse[64];       // xy texel position, z radius (texels), w depth (yards)\n"
    "    int4 wsCount;               // x impulses, yz the field's corner (absolute texels)\n"
    "    row_major float4x4 wsInvProj;\n"
    "    float4 wsViewport;          // the world viewport: x left, y top, z width, w height\n"
    "    float4 wsDepthRange;        // x min, y max, z 1 / (max - min)\n"
    "    float4 wsProjW;             // clip w = dot(float4(view position, 1), wsProjW)\n"
    "    float4 wsFoam;              // x foam kept a step, y foam a yard of disturbance makes, z foam from fast crests, w yards a unit of wsImpact\n"
    "    float4 wsBubble;            // x bubble chance per cell and step, y yards a bubble lifts, z its radius (texels), w its foam\n"
    "    float4 wsThick;             // x 1 = viscous (magma, slime), y the surface kept a step as it settles back\n"
    "};\n"
    "\n"
    "Texture2D<float4> wsField : register(t0);  // x the height now, y a step ago, z foam\n"
    "Texture2D<uint> wsImpact : register(t2);   // droplets that fell back this frame (D3d11Water's particles), fixed point\n"
    "#if GX_MSAA\n"
    "Texture2DMS<float> wsDepth : register(t1);\n"
    "float WsDepthAt(int2 p) {\n"
    "    return wsDepth.Load(p, 0);\n"
    "}\n"
    "#else\n"
    "Texture2D<float> wsDepth : register(t1);\n"
    "float WsDepthAt(int2 p) {\n"
    "    return wsDepth.Load(int3(p, 0));\n"
    "}\n"
    "#endif\n"
    "\n"
    "float4 FullscreenVs(uint id : SV_VertexID) : SV_Position {\n"
    "    float2 uv = float2((id << 1) & 2, id & 2);\n"
    "    return float4(uv * float2(2.0, -2.0) + float2(-1.0, 1.0), 0.0, 1.0);\n"
    "}\n"
    "\n"
    "float4 WsTap(int2 p) {\n"
    "    int n = wsShift.w;\n"
    "    if (p.x < 0 || p.y < 0 || p.x >= n || p.y >= n) {\n"
    "        return 0.0;\n"
    "    }\n"
    "    return wsField.Load(int3(p, 0));\n"
    "}\n"
    "\n"
    "uint WsHash(uint x) {\n"
    "    x ^= x >> 16;\n"
    "    x *= 0x7FEB352Du;\n"
    "    x ^= x >> 15;\n"
    "    x *= 0x846CA68Bu;\n"
    "    x ^= x >> 16;\n"
    "    return x;\n"
    "}\n"
    "\n"
    "// a raindrop lands on this texel this step: the hash of its place in the world and the step\n"
    "bool WsDrop(int2 p) {\n"
    "    uint2 a = uint2(p + wsCount.yz);\n"
    "    uint r = WsHash(a.x * 0x9E3779B1u ^ WsHash(a.y ^ ((uint)wsShift.z * 0x85EBCA77u)));\n"
    "    return (r & 0xFFFFFFu) * (1.0 / 16777216.0) < wsWave.z;\n"
    "}\n"
    "\n"
    "// magma and slime bubble: on a grid of 4-texel cells (absolute, so they stay put in the world) a bubble may rise in a\n"
    "// cell this step, somewhere in it, and lifts the surface by a Gaussian; x the lift, y its foam\n"
    "float2 WsBubbles(int2 p) {\n"
    "    if (wsBubble.x <= 0.0) {\n"
    "        return 0.0;\n"
    "    }\n"
    "\n"
    "    int2 a = p + wsCount.yz;\n"
    "    int2 cell = int2(floor(float2(a) / 4.0));\n"
    "    float r2 = max(wsBubble.z * wsBubble.z, 0.25);\n"
    "    float2 sum = 0.0;\n"
    "\n"
    "    [unroll] for (int y = -1; y <= 1; y++) {\n"
    "        [unroll] for (int x = -1; x <= 1; x++) {\n"
    "            uint2 c = uint2(cell + int2(x, y));\n"
    "            uint h = WsHash(c.x * 0x9E3779B1u ^ WsHash(c.y ^ ((uint)wsShift.z * 0x85EBCA77u) ^ 0x51ED270Bu));\n"
    "\n"
    "            if ((h & 0xFFFFu) * (1.0 / 65536.0) < wsBubble.x) {\n"
    "                // where in the cell, and how big (a few large, most small)\n"
    "                float2 at = float2(cell + int2(x, y)) * 4.0 + float2((h >> 16) & 0xFFu, h >> 24) * (4.0 / 256.0);\n"
    "                float size = 0.5 + (float)(WsHash(h) & 0xFFu) * (1.0 / 255.0);\n"
    "                float2 d = float2(a) + 0.5 - at;\n"
    "                float g = exp(-dot(d, d) / (r2 * size * size));\n"
    "                sum += float2(wsBubble.y * size, wsBubble.w) * g;\n"
    "            }\n"
    "        }\n"
    "    }\n"
    "\n"
    "    return sum;\n"
    "}\n"
    "\n"
    "uint WsImpactAt(int2 p) {\n"
    "    int n = wsShift.w;\n"
    "    if (p.x < 0 || p.y < 0 || p.x >= n || p.y >= n) {\n"
    "        return 0u;\n"
    "    }\n"
    "    return wsImpact.Load(int3(p, 0));\n"
    "}\n"
    "\n"
    "// one step of the field; x the height now, y a step ago, z the foam on it. Water: the damped wave equation, and a\n"
    "// disturbance pushes the surface (it rings out). Magma and slime are viscous: their motion is damped hard and the\n"
    "// surface settles back to level, a disturbance displaces it without a push, so a dent oozes shut and a bubble's dome\n"
    "// sinks back instead of ringing\n"
    "float4 SimPs(float4 pos : SV_Position) : SV_Target0 {\n"
    "    int2 p = int2(pos.xy);\n"
    "    int2 q = p + wsShift.xy;\n"
    "    float4 c = WsTap(q);\n"
    "    float4 l = WsTap(q - int2(1, 0));\n"
    "    float4 r = WsTap(q + int2(1, 0));\n"
    "    float4 d = WsTap(q - int2(0, 1));\n"
    "    float4 u = WsTap(q + int2(0, 1));\n"
    "    float lap = l.x + r.x + d.x + u.x - 4.0 * c.x;\n"
    "    bool viscous = wsThick.x > 0.5;\n"
    "    float h = viscous ? c.x + (c.x - c.y) * wsWave.y + wsWave.x * lap : (2.0 * c.x - c.y + wsWave.x * lap) * wsWave.y;\n"
    "    float prev = c.x;\n"
    "    // what this step's disturbances move the surface by (up is positive); a viscous surface's settling back is one, so\n"
    "    // it does not gather momentum\n"
    "    float moved = viscous ? c.x * (wsThick.y - 1.0) : 0.0;\n"
    "    // foam spreads a little and fades\n"
    "    float foam = (c.z * 0.6 + (l.z + r.z + d.z + u.z) * 0.1) * wsFoam.x;\n"
    "\n"
    "    for (int k = 0; k < wsCount.x; k++) {\n"
    "        float4 im = wsImpulse[k];\n"
    "        float2 d = float2(p) + 0.5 - im.xy;\n"
    "        float r2 = max(im.z * im.z, 0.25);\n"
    "        float dd = dot(d, d);\n"
    "\n"
    "        if (dd < 9.0 * r2) {\n"
    "            float g = exp(-dd / r2);\n"
    "            moved -= im.w * g;\n"
    "            foam += abs(im.w) * g * wsFoam.y;\n"
    "        }\n"
    "    }\n"
    "\n"
    "    if (wsWave.z > 0.0) {\n"
    "        // a drop pushes its texel down and half as much around it, so it does not ring at the grid's frequency\n"
    "        float drop = WsDrop(p) ? 1.0 : 0.0;\n"
    "        drop += 0.5 * ((WsDrop(p + int2(1, 0)) ? 1.0 : 0.0) + (WsDrop(p - int2(1, 0)) ? 1.0 : 0.0) + (WsDrop(p + int2(0, 1)) ? 1.0 : 0.0) + (WsDrop(p - int2(0, 1)) ? 1.0 : 0.0));\n"
    "        moved -= drop * wsWave.w;\n"
    "    }\n"
    "\n"
    "    // bubbles rising through magma and slime lift it, and stir it as they burst\n"
    "    float2 bubble = WsBubbles(p);\n"
    "    moved += bubble.x;\n"
    "    foam += bubble.y;\n"
    "\n"
    "    // drops back in the liquid, spread like a raindrop\n"
    "    float hit = (float)WsImpactAt(p) + 0.5 * (float)(WsImpactAt(p + int2(1, 0)) + WsImpactAt(p - int2(1, 0)) + WsImpactAt(p + int2(0, 1)) + WsImpactAt(p - int2(0, 1)));\n"
    "    hit *= wsFoam.w;\n"
    "    moved -= hit;\n"
    "    foam += hit * wsFoam.y * 0.5;\n"
    "    h += moved;\n"
    "\n"
    "    // a crest that moves fast whitens (a viscous surface by its own motion, not the displacement)\n"
    "    foam += max(abs(h - prev - (viscous ? moved : 0.0)) - 0.0015, 0.0) * wsFoam.z;\n"
    "\n"
    "    // displaced, not pushed: a step ago it stood where it stands now, but for its own motion\n"
    "    if (viscous) {\n"
    "        prev += moved;\n"
    "    }\n"
    "\n"
    "    // the border absorbs what reaches it instead of reflecting it\n"
    "    float edge = (float)min(min(p.x, p.y), min(wsShift.w - 1 - p.x, wsShift.w - 1 - p.y));\n"
    "    float keep = lerp(0.8, 1.0, saturate(edge / 24.0));\n"
    "    return float4(clamp(h * keep, -0.3, 0.3), clamp(prev * keep, -0.3, 0.3), saturate(foam * keep), 0.0);\n"
    "}\n"
    "\n"
    "// the opaque scene's depth as clip w (the distance along the view axis); 0 where the sky shows\n"
    "float4 DepthPs(float4 pos : SV_Position) : SV_Target0 {\n"
    "    float d = WsDepthAt(int2(pos.xy));\n"
    "\n"
    "    if (d > wsDepthRange.y + 0.00001 || d >= 0.99999) {\n"
    "        return 0.0;\n"
    "    }\n"
    "\n"
    "    // D3D9 drew this pixel's geometry half a pixel up and left of where D3D11 samples it (GxFinishVertex)\n"
    "    float2 ndc = float2((pos.x - 0.5 - wsViewport.x) / wsViewport.z * 2.0 - 1.0, 1.0 - (pos.y - 0.5 - wsViewport.y) / wsViewport.w * 2.0);\n"
    "    float4 h = mul(float4(ndc, (d - wsDepthRange.x) * wsDepthRange.z, 1.0), wsInvProj);\n"
    "    float3 v = h.xyz / h.w;\n"
    "    return max(dot(float4(v, 1.0), wsProjW), 0.0001);\n"
    "}\n";

// After s_hlslWaterConstants (the view, projection, sky and sun of the frame). Splash droplets and mist: a ring of
// s_maxParticles in a structured buffer. EmitCs starts this frame's ones from the emitters, UpdateCs moves them (gravity,
// drag) and turns a droplet falling back through the water into an impact on the height field, ParticleVs / ParticlePs
// draw them as camera-facing quads, droplets stretched along their velocity, lit by the sky and sun; no texture.
// Particle space is world space less a fixed origin (D3d11Water::m_particleOrigin), so the particles stay put while the
// render origin moves
const char* const s_hlslWaterParticles =
    "struct WxParticle {\n"
    "    float3 pos;\n"
    "    float life;      // seconds left; 0 = free\n"
    "    float3 vel;\n"
    "    float size;      // yards\n"
    "    float waterZ;    // the surface it rose from\n"
    "    float kind;      // 0 a drop, 1 mist, 2 a sheet (slime: a strand), 3 an ember\n"
    "    float age;\n"
    "    float maxLife;\n"
    "    float3 color;    // linear: magma's glow, slime's body\n"
    "    float liquid;    // 0 water, 1 magma, 2 slime\n"
    "};\n"
    "\n"
    "cbuffer GxWaterParticles : register(b6) {\n"
    "    float4 wpOffset;         // xyz particle space to render space, w the step (seconds)\n"
    "    float4 wpField;          // xy the height field's corner (particle space), z 1 / texel, w its size (texels)\n"
    "    float4 wpSim;            // x gravity (yards / s2), y droplet drag (1 / s), z impact units a yard, w yards a droplet pushes\n"
    "    uint4 wpEmit;            // x the first slot, y the capacity, z a seed, w particles to start\n"
    "    uint4 wpCount;           // x emitters, y 1 = the water's field is there, z 1 = the thick liquids' field is there\n"
    "    float4 wpEmitters[96];   // three each: xyz place (particle space), w end of its share; x up speed, y out speed, z radius, w kind; rgb colour, w liquid\n"
    "};\n"
    "\n"
    "RWStructuredBuffer<WxParticle> wpParticles : register(u0);\n"
    "RWTexture2D<uint> wpImpact : register(u1);       // the water's field\n"
    "RWTexture2D<uint> wpImpactThick : register(u2);  // magma's and slime's\n"
    "StructuredBuffer<WxParticle> wpParticlesIn : register(t21);\n"
    "\n"
    "uint WpHash(uint x) {\n"
    "    x ^= x >> 16;\n"
    "    x *= 0x7FEB352Du;\n"
    "    x ^= x >> 15;\n"
    "    x *= 0x846CA68Bu;\n"
    "    x ^= x >> 16;\n"
    "    return x;\n"
    "}\n"
    "\n"
    "float WpRand(inout uint s) {\n"
    "    s = WpHash(s);\n"
    "    return (s & 0xFFFFFFu) * (1.0 / 16777216.0);\n"
    "}\n"
    "\n"
    "[numthreads(64, 1, 1)]\n"
    "void EmitCs(uint3 id : SV_DispatchThreadID) {\n"
    "    if (id.x >= wpEmit.w) {\n"
    "        return;\n"
    "    }\n"
    "\n"
    "    uint e = 0;\n"
    "\n"
    "    for (; e + 1 < wpCount.x; e++) {\n"
    "        if (id.x < (uint)wpEmitters[e * 3].w) {\n"
    "            break;\n"
    "        }\n"
    "    }\n"
    "\n"
    "    float4 a = wpEmitters[e * 3];\n"
    "    float4 b = wpEmitters[e * 3 + 1];\n"
    "    float4 c = wpEmitters[e * 3 + 2];\n"
    "    uint s = WpHash(id.x * 0x9E3779B1u ^ wpEmit.z);\n"
    "    float angle = WpRand(s) * 6.2831853;\n"
    "    float r = sqrt(WpRand(s));\n"
    "    float2 dir = float2(cos(angle), sin(angle));\n"
    "    // kinds: 0 a drop, 1 mist, 2 a sheet (the torn crown of a splash, short-lived and stretched; of slime, a strand), 3 an\n"
    "    // ember (magma: a spark that rises)\n"
    "    uint kind = (uint)(b.w + 0.5);\n"
    "    uint liquid = (uint)(c.w + 0.5);\n"
    "    WxParticle q;\n"
    "    // a sheet leaves from the crown's ring, a drop from anywhere in it\n"
    "    float place = kind == 2u ? 0.8 + 0.2 * r : r;\n"
    "    q.pos = a.xyz + float3(dir * (place * b.z), 0.03);\n"
    "    // the middle of a splash goes highest, its rim widest\n"
    "    float up = b.x * (0.5 + 0.5 * WpRand(s)) * (1.15 - 0.4 * place);\n"
    "    float spread = b.y * (0.3 + 0.7 * WpRand(s)) * (0.4 + 0.6 * place);\n"
    "    q.vel = float3(dir * spread, up);\n"
    "    float k = WpRand(s);\n"
    "    float lifeRand = WpRand(s);\n"
    "\n"
    "    if (liquid == 1u) {\n"
    "        // magma: heavy globs, a few large; embers tiny\n"
    "        q.size = kind == 3u ? 0.004 + 0.008 * k : 0.03 + 0.06 * k * k;\n"
    "        q.maxLife = kind == 3u ? 0.8 + 1.4 * lifeRand : 3.0;\n"
    "    } else if (liquid == 2u) {\n"
    "        // slime: gobs, and strands torn off the crown that hang a while\n"
    "        q.size = kind == 2u ? 0.02 + 0.02 * k : 0.015 + 0.045 * k * k;\n"
    "        q.maxLife = kind == 2u ? 0.5 + 0.4 * lifeRand : 3.0;\n"
    "    } else {\n"
    "        // most droplets are tiny, a few large (radius, yards)\n"
    "        q.size = kind == 1u ? 0.25 + 0.3 * k : (kind == 2u ? 0.035 + 0.035 * k : 0.005 + 0.017 * k * k);\n"
    "        q.maxLife = kind == 1u ? 0.7 + 0.8 * lifeRand : (kind == 2u ? 0.25 + 0.25 * lifeRand : 3.0);\n"
    "    }\n"
    "\n"
    "    q.life = q.maxLife;\n"
    "    q.waterZ = a.z;\n"
    "    q.kind = (float)kind;\n"
    "    q.age = 0.0;\n"
    "    q.color = c.rgb;\n"
    "    q.liquid = (float)liquid;\n"
    "    wpParticles[(wpEmit.x + id.x) % wpEmit.y] = q;\n"
    "}\n"
    "\n"
    "[numthreads(64, 1, 1)]\n"
    "void UpdateCs(uint3 id : SV_DispatchThreadID) {\n"
    "    if (id.x >= wpEmit.y) {\n"
    "        return;\n"
    "    }\n"
    "\n"
    "    WxParticle q = wpParticles[id.x];\n"
    "\n"
    "    if (q.life <= 0.0) {\n"
    "        return;\n"
    "    }\n"
    "\n"
    "    float dt = wpOffset.w;\n"
    "    bool mist = abs(q.kind - 1.0) < 0.5;\n"
    "    bool ember = q.kind > 2.5;\n"
    "    bool thick = q.liquid > 0.5;\n"
    "    bool strand = thick && abs(q.kind - 2.0) < 0.5;\n"
    "\n"
    "    if (ember) {\n"
    "        // an ember rides the heat above the magma: it rises, slows, and flutters\n"
    "        uint s = WpHash(id.x * 0x27D4EB2Fu ^ (uint)(q.age * 30.0));\n"
    "        q.vel.z += wpSim.x * 0.12 * dt;\n"
    "        q.vel.xy += (float2(WpRand(s), WpRand(s)) - 0.5) * (6.0 * dt);\n"
    "        q.vel *= exp(-1.6 * dt);\n"
    "    } else {\n"
    "        // mist hangs and drifts up a little before it settles; drops and sheets fall; a slime strand hangs\n"
    "        q.vel.z -= wpSim.x * dt * (mist ? 0.1 : (strand ? 0.6 : 1.0));\n"
    "        float drag = mist ? 2.5 : (strand ? 1.2 : (thick ? (q.liquid < 1.5 ? 0.25 : 0.5) : wpSim.y));\n"
    "        q.vel *= exp(-drag * dt);\n"
    "    }\n"
    "\n"
    "    q.pos += q.vel * dt;\n"
    "    q.age += dt;\n"
    "    q.life -= dt;\n"
    "\n"
    "    if (mist) {\n"
    "        q.size += dt * 0.35;\n"
    "    } else if (!ember && q.pos.z < q.waterZ && q.vel.z < 0.0) {\n"
    "        // back in the liquid: a small ring on its height field (heavier for magma and slime)\n"
    "        if (thick ? wpCount.z : wpCount.y) {\n"
    "            int2 t = int2(floor((q.pos.xy - wpField.xy) * wpField.z));\n"
    "\n"
    "            if (all(t >= 0) && all(t < (int)wpField.w)) {\n"
    "                uint units = (uint)(wpSim.w * min(q.size / 0.02, 4.0) * (thick ? 2.0 : 1.0) * wpSim.z);\n"
    "\n"
    "                if (thick) {\n"
    "                    InterlockedAdd(wpImpactThick[t], units);\n"
    "                } else {\n"
    "                    InterlockedAdd(wpImpact[t], units);\n"
    "                }\n"
    "            }\n"
    "        }\n"
    "\n"
    "        q.life = 0.0;\n"
    "    }\n"
    "\n"
    "    wpParticles[id.x] = q;\n"
    "}\n"
    "\n"
    "struct WpVaryings {\n"
    "    float4 pos : SV_Position;\n"
    "    float2 uv : TEXCOORD0;       // -1 to 1 across the quad, y along the motion\n"
    "    float alpha : TEXCOORD1;\n"
    "    float kind : TEXCOORD2;\n"
    "    float3 sky : TEXCOORD3;      // what the rim reflects, linear\n"
    "    float3 sun : TEXCOORD4;      // the sun's colour, linear, 0 indoors and at night\n"
    "    float3 sunQuad : TEXCOORD5;  // toward the sun in the quad's frame (x side, y along, z toward the eye)\n"
    "    float lens : TEXCOORD6;      // pixels the world behind a droplet is turned over by\n"
    "    float4 color : TEXCOORD7;    // rgb the particle's colour (linear), w its liquid\n"
    "    float heat : TEXCOORD8;      // magma: 1 fresh from the surface, 0 cooled\n"
    "};\n"
    "\n"
    "WpVaryings ParticleVs(uint id : SV_VertexID) {\n"
    "    WpVaryings o = (WpVaryings)0;\n"
    "    WxParticle q = wpParticlesIn[id / 6];\n"
    "\n"
    "    if (q.life <= 0.0) {\n"
    "        // behind the near plane: nothing drawn\n"
    "        o.pos = float4(0.0, 0.0, -1.0, 1.0);\n"
    "        return o;\n"
    "    }\n"
    "\n"
    "    static const float2 corners[6] = { float2(-1, -1), float2(1, -1), float2(-1, 1), float2(1, -1), float2(1, 1), float2(-1, 1) };\n"
    "    float2 uv = corners[id % 6];\n"
    "    bool mist = abs(q.kind - 1.0) < 0.5;\n"
    "    bool sheet = abs(q.kind - 2.0) < 0.5;\n"
    "    bool ember = q.kind > 2.5;\n"
    "    bool thick = q.liquid > 0.5;\n"
    "    float3 pv = mul(float4(q.pos + wpOffset.xyz, 1.0), gxWaterView).xyz;\n"
    "    float3 vv = mul(q.vel, (float3x3)gxWaterView);\n"
    "    float2 axis = dot(vv.xy, vv.xy) > 1e-6 ? normalize(vv.xy) : float2(0.0, 1.0);\n"
    "    float2 side = float2(-axis.y, axis.x);\n"
    "\n"
    "    // the size on screen: a droplet smaller than a pixel is drawn a pixel wide and fainter, so it does not flicker\n"
    "    float w = max(dot(float4(pv, 1.0), float4(gxWaterProj._m03, gxWaterProj._m13, gxWaterProj._m23, gxWaterProj._m33)), 0.01);\n"
    "    float pixelsPerYard = 0.5 * gxWaterViewport.w * abs(gxWaterProj._m11) / w;\n"
    "    float size = q.size;\n"
    "    float faint = 1.0;\n"
    "\n"
    "    if (!mist && size * pixelsPerYard < 0.8) {\n"
    "        faint = size * pixelsPerYard / 0.8;\n"
    "        size = 0.8 / pixelsPerYard;\n"
    "    }\n"
    "\n"
    "    // motion blur: a droplet streaks along its path over about a 30th of a second, its light spread over the streak;\n"
    "    // a sheet stretches more, torn along its flight; magma and slime are thick, they stretch less (a strand more)\n"
    "    float stretch = mist ? 0.0 : (sheet ? (thick ? 0.12 : 0.08) : (ember ? 0.05 : (thick ? 0.015 : 0.03)));\n"
    "    float along = size + length(vv.xy) * stretch;\n"
    "    // a sheet is a thin torn strip\n"
    "    pv.xy += axis * (uv.y * along) + side * (uv.x * size * (sheet ? 0.35 : 1.0));\n"
    "    o.pos = mul(float4(pv, 1.0), gxWaterProj);\n"
    "    o.pos.xy += float2(gxWaterTarget.x, -gxWaterTarget.y) * o.pos.w;\n"
    "    o.uv = uv;\n"
    "    float fade = saturate(q.age * 30.0) * saturate(q.life / (mist ? q.maxLife * 0.7 : (sheet || ember ? q.maxLife * 0.6 : 0.15)));\n"
    "    float streak = mist ? 1.0 : sqrt(size / along);\n"
    "    float opacity = mist ? 0.04 : (sheet ? (thick ? 0.85 : 0.55) : (ember ? 1.0 : (thick ? 1.0 : 0.9)));\n"
    "    o.alpha = fade * faint * streak * opacity;\n"
    "    o.kind = q.kind;\n"
    "    o.lens = size * pixelsPerYard;\n"
    "    o.color = float4(q.color, q.liquid);\n"
    "    // a glob of magma cools in the air in about a second and a half, an ember dims over its life\n"
    "    o.heat = ember ? saturate(q.life / q.maxLife) : saturate(1.0 - q.age / 1.6);\n"
    "\n"
    "    float3 sky = lerp(gxWaterAmbient.rgb, gxWaterSky[0].rgb * 0.4 + gxWaterSky[1].rgb * 0.4 + gxWaterSky[5].rgb * 0.2, gxWaterAmbient.w);\n"
    "    o.sky = sky;\n"
    "    o.sun = gxWaterSunColor.rgb * (gxWaterSunDir.w * gxWaterAmbient.w);\n"
    "    float3 sunView = mul(gxWaterSunDir.xyz, (float3x3)gxWaterView);\n"
    "    // the view looks along +z: toward the eye is -z\n"
    "    o.sunQuad = normalize(float3(dot(sunView.xy, side), dot(sunView.xy, axis), -sunView.z));\n"
    "    return o;\n"
    "}\n"
    "\n"
    "float4 ParticlePs(WpVaryings i) : SV_Target0 {\n"
    "    float r2 = dot(i.uv, i.uv);\n"
    "\n"
    "    if (r2 > 1.0) {\n"
    "        discard;\n"
    "    }\n"
    "\n"
    "    float r = sqrt(r2);\n"
    "    float liquid = i.color.w;\n"
    "\n"
    "    if (abs(i.kind - 1.0) < 0.5) {\n"
    "        // mist: a soft puff, lit like the sky and the sun through it\n"
    "        float3 m = i.sky * 0.55 + i.sun * 0.2;\n"
    "        return float4(pow(max(m, 0.0), 1.0 / 2.2), (1.0 - r2) * (1.0 - r2) * i.alpha);\n"
    "    }\n"
    "\n"
    "    float3 n = float3(i.uv.x, i.uv.y, sqrt(1.0 - r2));\n"
    "\n"
    "    if (i.kind > 2.5) {\n"
    "        // an ember: a point of light, a hot core in a soft halo, past 1 in the HDR scene\n"
    "        float core = exp(-r2 * 6.0);\n"
    "        float3 e = lerp(i.color.rgb, WxHotter(i.color.rgb), core * 0.6) * (core * 2.5 + 0.4) * gxWaterLiquid.x * (0.3 + 0.7 * i.heat);\n"
    "        return float4(pow(max(WxFit(e), 0.0), 1.0 / 2.2), i.alpha * saturate((1.0 - r) * 2.0));\n"
    "    }\n"
    "\n"
    "    if (liquid > 0.5 && liquid < 1.5) {\n"
    "        // a glob of magma: molten through the middle, a darker crust at its rim as it cools in the air\n"
    "        float heat = i.heat * (0.55 + 0.45 * n.z);\n"
    "        float3 crust = i.color.rgb * 0.08 * (i.sky + i.sun * saturate(dot(n, i.sunQuad)));\n"
    "        float3 molten = WxFit(lerp(i.color.rgb, WxHotter(i.color.rgb), heat * heat * 0.7) * (0.4 + 2.2 * heat) * gxWaterLiquid.x);\n"
    "        float3 c = lerp(crust, molten, saturate(heat * 1.4));\n"
    "        float edge = saturate((1.0 - r) * max(i.lens, 1.0));\n"
    "        return float4(pow(max(c, 0.0), 1.0 / 2.2), i.alpha * edge);\n"
    "    }\n"
    "\n"
    "    if (liquid > 1.5) {\n"
    "        // a gob of slime: its own colour lit by the sky and the sun, a little of its own glow, wet: the sky at its rim and\n"
    "        // a sharp glint\n"
    "        float ndl = saturate(dot(n, i.sunQuad));\n"
    "        float3 body = i.color.rgb * (gxWaterLiquid.y + (1.0 - gxWaterLiquid.y) * (i.sky * 1.6 + i.sun * ndl));\n"
    "        float fresnel = 0.04 + 0.96 * pow(1.0 - n.z, 5.0);\n"
    "        float3 c = lerp(body, i.sky, fresnel * 0.6);\n"
    "        float3 h = normalize(i.sunQuad + float3(0.0, 0.0, 1.0));\n"
    "        c += i.sun * (pow(saturate(dot(n, h)), 90.0) * 3.0);\n"
    "        float edge = saturate((1.0 - r) * max(i.lens, 1.0));\n"
    "        return float4(pow(max(c, 0.0), 1.0 / 2.2), i.alpha * edge);\n"
    "    }\n"
    "\n"
    "    // a droplet is a small sphere of water: the world behind it, turned over and a little darker, through its middle; the\n"
    "    // sky reflected at its rim (Fresnel); a glint where the sun meets its surface\n"
    "    float2 lens = -i.uv * (i.lens * 0.85);\n"
    "    float2 at = clamp(i.pos.xy + lens, gxWaterViewport.xy + 0.5, gxWaterViewport.xy + gxWaterViewport.zw - 0.5);\n"
    "    float3 behind = pow(max(gxWaterScene.SampleLevel(gxWaterLinear, at * gxWaterTarget.xy, 0.0).rgb, 0.0), 2.2);\n"
    "    float fresnel = 0.03 + 0.97 * pow(1.0 - n.z, 4.0);\n"
    "    float3 c = lerp(behind * 0.95, i.sky, fresnel);\n"
    "    float3 h = normalize(i.sunQuad + float3(0.0, 0.0, 1.0));\n"
    "    c += i.sun * (pow(saturate(dot(n, h)), 120.0) * 6.0);\n"
    "    // a crisp edge, as water has, softened by a pixel\n"
    "    float edge = saturate((1.0 - r) * max(i.lens, 1.0));\n"
    "    return float4(pow(max(c, 0.0), 1.0 / 2.2), i.alpha * edge);\n"
    "}\n";

// After s_hlslCommon, s_hlslPatchPoint and s_hlslWaterConstants. The water's triangles (a list: the liquid geometry factories build lists
// on this device) are cut finer near the eye, down to gxWaterTess.z yards an edge, and every new vertex is moved up or
// down by the height field: the waves are geometry. An edge's factor depends only on its two ends, so the neighbouring
// triangle cuts it the same way and no crack opens
const char* const s_hlslWaterTessellation =
    "struct GxWaterPatch {\n"
    "    float edges[3] : SV_TessFactor;\n"
    "    float inside : SV_InsideTessFactor;\n"
    "};\n"
    "\n"
    "float WxEdgeFactor(float4 a, float4 b) {\n"
    "    if (gxWaterTess.x <= 0.0 || a.w < 0.5 || b.w < 0.5) {\n"
    "        return 1.0;\n"
    "    }\n"
    "\n"
    "    float3 mid = (a.xyz + b.xyz) * 0.5;\n"
    "    float dist = length(mid);\n"
    "    float3 midWorld = mul(float4(mid, 1.0), gxWaterViewInv).xyz;\n"
    "    float2 uv = (midWorld.xy - gxWaterField.xy) * gxWaterField.z;\n"
    "\n"
    "    // only where the height field is, and not far off\n"
    "    if (gxWaterFieldExtra.y <= 0.0 || any(uv < -0.05) || any(uv > 1.05) || dist > 90.0) {\n"
    "        return 1.0;\n"
    "    }\n"
    "\n"
    "    float target = max(gxWaterTess.z, dist * 0.02);\n"
    "    return clamp(length(a.xyz - b.xyz) / target, 1.0, gxWaterTess.y);\n"
    "}\n"
    "\n"
    "GxWaterPatch WaterPatch(InputPatch<GxPatchPoint, 3> p) {\n"
    "    GxWaterPatch o;\n"
    "    // edge i lies opposite control point i\n"
    "    o.edges[0] = WxEdgeFactor(p[1].gxP, p[2].gxP);\n"
    "    o.edges[1] = WxEdgeFactor(p[2].gxP, p[0].gxP);\n"
    "    o.edges[2] = WxEdgeFactor(p[0].gxP, p[1].gxP);\n"
    "    o.inside = max(o.edges[0], max(o.edges[1], o.edges[2]));\n"
    "    return o;\n"
    "}\n"
    "\n"
    "[domain(\"tri\")]\n"
    "[partitioning(\"fractional_odd\")]\n"
    "[outputtopology(\"triangle_cw\")]\n"
    "[outputcontrolpoints(3)]\n"
    "[patchconstantfunc(\"WaterPatch\")]\n"
    "[maxtessfactor(32.0)]\n"
    "GxPatchPoint WaterHs(InputPatch<GxPatchPoint, 3> p, uint i : SV_OutputControlPointID) {\n"
    "    return p[i];\n"
    "}\n"
    "\n"
    "#define WX_LERP(m) o.m = p[0].m * b.x + p[1].m * b.y + p[2].m * b.z\n"
    "\n"
    "[domain(\"tri\")]\n"
    "GxVaryings WaterDs(GxWaterPatch c, float3 b : SV_DomainLocation, const OutputPatch<GxPatchPoint, 3> p) {\n"
    "    GxPatchPoint o;\n"
    "    WX_LERP(pos);\n"
    "    WX_LERP(c0);\n"
    "    WX_LERP(c1);\n"
    "    WX_LERP(t0);\n"
    "    WX_LERP(t1);\n"
    "    WX_LERP(t2);\n"
    "    WX_LERP(t3);\n"
    "    WX_LERP(t4);\n"
    "    WX_LERP(t5);\n"
    "    WX_LERP(t6);\n"
    "    WX_LERP(t7);\n"
    "    WX_LERP(t8);\n"
    "    WX_LERP(t9);\n"
    "    WX_LERP(n0);\n"
    "    WX_LERP(tg0);\n"
    "    WX_LERP(bn0);\n"
    "    WX_LERP(fog);\n"
    "    WX_LERP(psize);\n"
    "    WX_LERP(gxN);\n"
    "    WX_LERP(gxP);\n"
    "    WX_LERP(gxM);\n"
    "    WX_LERP(gxF);\n"
    "    WX_LERP(clip0);\n"
    "    WX_LERP(clip1);\n"
    "\n"
    "    if (gxWaterTess.x > 0.0 && o.gxP.w > 0.5) {\n"
    "        float3 w = mul(float4(o.gxP.xyz, 1.0), gxWaterViewInv).xyz;\n"
    "        w.z += WxRipple(w.xy).x * gxWaterTess.w;\n"
    "        o.gxP.xyz = mul(float4(w, 1.0), gxWaterView).xyz;\n"
    "        o.pos = mul(float4(o.gxP.xyz, 1.0), gxWaterProj);\n"
    "        // D3D9's rasterisation, as GxFinishVertex: half a pixel right and down\n"
    "        o.pos.xy += float2(gxWaterTarget.x, -gxWaterTarget.y) * o.pos.w;\n"
    "    }\n"
    "\n"
    "    return GxFromPatchPoint(o);\n"
    "}\n";

}
